<section class="container page-heading"><span class="section-kicker">Katalog</span><h1>Kelola paket foto</h1><p>Harga dan durasi disimpan sebagai snapshot pada reservasi agar perubahan paket berikutnya tidak mengubah tagihan lama.</p></section>
<section class="container admin-page"><div class="row g-4 align-items-start"><div class="col-lg-5"><div class="surface surface-pad"><h2 class="h5 mb-4"><?= $editing ? 'Ubah paket' : 'Tambah paket baru' ?></h2><form method="post" action="<?= e(url('admin-packages')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id_paket" value="<?= (int)($editing['id_paket'] ?? 0) ?>"><div class="mb-3"><label class="form-label" for="nama_paket">Nama paket</label><input class="form-control" id="nama_paket" name="nama_paket" required maxlength="100" value="<?= e($editing['nama_paket'] ?? '') ?>"></div><div class="mb-3"><label class="form-label" for="deskripsi">Deskripsi / fasilitas</label><textarea class="form-control" id="deskripsi" name="deskripsi" rows="3" required><?= e($editing['deskripsi'] ?? '') ?></textarea></div><div class="row g-3"><div class="col-sm-7"><label class="form-label" for="harga_paket">Harga (Rp)</label><input class="form-control" id="harga_paket" type="number" name="harga_paket" min="1" step="1000" required value="<?= e($editing['harga_paket'] ?? '') ?>"></div><div class="col-sm-5"><label class="form-label" for="durasi_menit">Durasi (menit)</label><input class="form-control" id="durasi_menit" type="number" name="durasi_menit" min="30" max="360" step="30" required value="<?= e($editing['durasi_menit'] ?? '60') ?>"></div></div><div class="mt-3 mb-3"><label class="form-label" for="gambar">Ilustrasi paket</label><select class="form-select" id="gambar" name="gambar"><?php foreach (['studio.svg'=>'Studio klasik','keluarga.svg'=>'Keluarga','wisuda.svg'=>'Wisuda','produk.svg'=>'Produk komersial'] as $filename=>$label): ?><option value="<?= e($filename) ?>" <?= ($editing['gambar'] ?? 'studio.svg')===$filename?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="mb-4"><label class="form-label">Layanan yang termasuk</label><?php if (!$services): ?><div class="notice">Tambahkan layanan terlebih dahulu.</div><?php else: ?><div class="border rounded-3 p-3" style="border-color:var(--line)!important"><?php foreach ($services as $service): ?><div class="form-check mb-2"><input class="form-check-input" type="checkbox" id="service<?= (int)$service['id_layanan'] ?>" name="layanan[]" value="<?= (int)$service['id_layanan'] ?>" <?= in_array((int)$service['id_layanan'], $selectedServiceIds ?? [], true)?'checked':'' ?>><label class="form-check-label" for="service<?= (int)$service['id_layanan'] ?>"><?= e($service['nama_layanan']) ?> <small class="muted">· <?= money($service['harga_satuan']) ?></small></label></div><?php endforeach; ?></div><?php endif; ?></div><button class="btn btn-copper w-100" type="submit">Simpan Paket</button><?php if ($editing): ?><a class="btn btn-link w-100 mt-2" href="<?= e(url('admin-packages')) ?>">Batal mengubah</a><?php endif; ?></form></div></div><div class="col-lg-7"><div class="surface"><div class="surface-pad"><h2 class="h5 mb-1">Katalog paket</h2><p class="form-note mb-0">Paket lama tidak dihapus permanen apabila sudah memiliki riwayat reservasi.</p></div><div class="table-wrap"><table class="table"><thead><tr><th>Paket</th><th>Harga / durasi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($packages as $package): ?><tr><td><div class="d-flex align-items-center gap-3"><img src="<?= e(asset('images/'.$package['gambar'])) ?>" alt="" style="width:62px;height:48px;object-fit:cover;border-radius:8px"><div><strong><?= e($package['nama_paket']) ?></strong><span class="subtext"><?= e($package['layanan_list'] ?: 'Belum ada layanan tertaut') ?></span></div></div></td><td class="no-wrap"><?= money($package['harga_paket']) ?><span class="subtext"><?= (int)$package['durasi_menit'] ?> menit</span></td><td><span class="badge-status <?= $package['aktif']?'success':'secondary' ?>"><?= $package['aktif']?'Aktif':'Nonaktif' ?></span></td><td><div class="small-actions"><a class="btn btn-sm btn-outline-dark" href="<?= e(url('admin-packages',['edit'=>$package['id_paket']])) ?>">Ubah</a><form method="post" action="<?= e(url('admin-packages')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id_paket" value="<?= (int)$package['id_paket'] ?>"><input type="hidden" name="active" value="<?= $package['aktif']?'0':'1' ?>"><button class="btn btn-sm <?= $package['aktif']?'btn-outline-danger':'btn-outline-success' ?>" data-confirm="<?= $package['aktif']?'Nonaktifkan':'Aktifkan' ?> paket ini?" type="submit"><?= $package['aktif']?'Nonaktifkan':'Aktifkan' ?></button></form></div></td></tr><?php endforeach; ?><?php if (!$packages): ?><tr><td colspan="4" class="muted text-center py-4">Belum ada paket.</td></tr><?php endif; ?></tbody></table></div></div></div></div></section>
